<h1>Tour plans</h1><p>Create a new journey, update existing plans, or remove tours from your website.</p><a class="button" href="#new-tour" id="new-tour-trigger">Add tour plan</a>
<?php
$editTours=tours();
$editTours[]=['id'=>0,'title'=>'','description'=>'','poster'=>'','prices'=>'[]','days'=>'[{"location":"","activities":[]}]'];
if($error && ($_POST['action']??'')==='tour') {
 foreach($editTours as &$draft) if((int)$draft['id']===(int)($_POST['id']??-1)) {
  $draft['title']=(string)($_POST['title']??'');$draft['description']=(string)($_POST['description']??'');$draftPrices=[];$draftDays=[];
  foreach([2,4,6] as $people) if(($_POST['prices'][$people]??'')!=='') $draftPrices[$people.' persons']=$_POST['prices'][$people];
  foreach((array)($_POST['days']??[]) as $day) $draftDays[]=['location'=>(string)($day['location']??''),'activities'=>explode("\n",(string)($day['activities']??''))];
  $draft['prices']=json_encode($draftPrices);$draft['days']=json_encode($draftDays?:[['location'=>'','activities'=>[]]]);
 } unset($draft);
}
?>
