on" class="button secondary remove-day">Remove day</button></fieldset><?php endforeach ?></div><button type="button" class="button secondary add-day">Add a day</button><div class="save-bar"><button class="button"><?= $t['id']?'Save tour plan':'Create tour plan' ?></button></div></form><?php if($t['id']): ?><form method="post" enctype="multipart/form-data" class="poster-form"><?= csrf_field() ?><input type="hidden" name="action" value="tour-poster"><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><fieldset class="poster-field photo-field"><legend>Itinerary poster</legend><img class="admin-photo poster-preview" src="<?= e($t['poster']?:'') ?>" alt="<?= e($t['title']) ?> poster preview" <?= empty($t['poster'])?'hidden':'' ?>><p class="poster-status"><?= empty($t['poster'])?'No itinerary poster added.':'Current itinerary poster' ?></p><?php if(!empty($t['poster'])): ?><a href="<?= e($t['poster']) ?>" target="_blank" rel="noopener">View full poster</a><?php endif ?><label><?= empty($t['poster'])?'Add itinerary poster':'Replace itinerary poster' ?><input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG or WebP, up to 5 MB. Choose a file and save to publish it.</small><div class="save-bar"><button class="button" name="poster_operation" value="save">Save poster</button><?php if(!empty($t['poster'])): ?><button class="button danger remove-poster" name="poster_operation" value="remove" formnovalidate>Remove poster</button><?php endif ?></div></fieldset></form><?php endif ?><?php if($t['id']): ?><form method="post" class="delete-tour-form" data-tour-name="<?= e($t['title']) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><button class="button danger" name="action" value="delete-tour">Delete tour plan</button><small>This removes the complete itinerary and its prices from the website.</small></form><?php endif ?></section><?php if(!$t['id']): ?></details><?php endif ?><?php endforeach ?>
